export function connectionsEvidence(record){if(!['statistics_lab','defects_lab','reciprocity_lab'].includes(record.action))return null;const e=record.result.learningEvidence||{},pair=e.comparison;return record.result.summary.map(s=>`${s.label}=${s.value}`).join('；')+`; symbolic steps${e.symbolic?.result?.correct?"verified":"Not verified"}; A/B complete evidence${pair?"saved":"not saved"}`+(pair?`

A parameters:${JSON.stringify(pair.A.input)}

B parameters:${JSON.stringify(pair.B.input)}

Comparative explanation:${pair.explanation||"Not filled in yet"}`:'');}
